CREATE TABLE IF NOT EXISTS "events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL REFERENCES "tenants"("id"), "name" text NOT NULL, "description" text, "event_date" date NOT NULL, "active" boolean NOT NULL DEFAULT true, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("tenant_id", "id"), CHECK (length(trim("name")) >= 2));
CREATE INDEX IF NOT EXISTS "events_tenant_date_idx" ON "events" ("tenant_id", "event_date");
CREATE TABLE IF NOT EXISTS "event_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL, "event_id" uuid NOT NULL, "kind" text NOT NULL, "procedure_id" uuid, "combo_id" uuid, "sessions" integer, FOREIGN KEY ("tenant_id", "event_id") REFERENCES "events"("tenant_id", "id"), FOREIGN KEY ("tenant_id", "procedure_id") REFERENCES "procedures"("tenant_id", "id"), FOREIGN KEY ("tenant_id", "combo_id") REFERENCES "combos"("tenant_id", "id"), CHECK ("kind" IN ('procedure', 'combo')), CHECK (("kind" = 'procedure' AND "procedure_id" IS NOT NULL AND "combo_id" IS NULL AND "sessions" >= 1) OR ("kind" = 'combo' AND "combo_id" IS NOT NULL AND "procedure_id" IS NULL AND "sessions" IS NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS "event_items_procedure_unique" ON "event_items" ("tenant_id", "event_id", "procedure_id") WHERE "procedure_id" IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "event_items_combo_unique" ON "event_items" ("tenant_id", "event_id", "combo_id") WHERE "combo_id" IS NOT NULL;
CREATE TABLE IF NOT EXISTS "event_contracts" ("tenant_id" uuid NOT NULL, "event_id" uuid NOT NULL, "contract_id" uuid NOT NULL, "title" text NOT NULL, PRIMARY KEY ("tenant_id", "event_id", "contract_id"), FOREIGN KEY ("tenant_id", "event_id") REFERENCES "events"("tenant_id", "id"), FOREIGN KEY ("tenant_id", "contract_id") REFERENCES "contracts"("tenant_id", "id"));
